-- lovable-cron-fallback-reviewed: bounded queue wakes on enqueue, checks at five-second intervals only while pending, unschedules after drain; no job enabled during implementation.
CREATE TABLE public.first_contact_settings(company_key text PRIMARY KEY DEFAULT 'crm:1' CHECK(company_key='crm:1'),enabled boolean NOT NULL DEFAULT false,instance text NOT NULL DEFAULT '',sender_phone text NOT NULL DEFAULT '',authorized_by uuid,interval_seconds integer NOT NULL DEFAULT 10 CHECK(interval_seconds BETWEEN 5 AND 300),revision uuid NOT NULL DEFAULT gen_random_uuid(),updated_at timestamptz NOT NULL DEFAULT now(),job_secret text,runtime_ready boolean NOT NULL DEFAULT false);
GRANT ALL ON public.first_contact_settings TO service_role; REVOKE ALL ON public.first_contact_settings FROM anon,authenticated; ALTER TABLE public.first_contact_settings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.first_contact_sequences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_key text NOT NULL DEFAULT 'crm:1' CHECK(company_key='crm:1'),lead_id uuid NOT NULL REFERENCES public.leads(id),submission_id text NOT NULL UNIQUE CHECK(length(submission_id) BETWEEN 1 AND 200),contact_key text NOT NULL UNIQUE,phone text NOT NULL,first_name text NOT NULL,lead_name text NOT NULL,instance text NOT NULL,sender_phone text NOT NULL,settings_revision uuid NOT NULL,consent_at timestamptz NOT NULL,consent_version text NOT NULL,form_origin text NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','unknown','failed','cancelled','completed')),reason text,next_step integer NOT NULL DEFAULT 1 CHECK(next_step BETWEEN 1 AND 5),due_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,moved_at timestamptz,inbound_id text,lease_id uuid,lease_until timestamptz);
GRANT ALL ON public.first_contact_sequences TO service_role; REVOKE ALL ON public.first_contact_sequences FROM anon,authenticated; ALTER TABLE public.first_contact_sequences ENABLE ROW LEVEL SECURITY;
CREATE INDEX first_contact_due ON public.first_contact_sequences(due_at) WHERE state='pending';
CREATE TABLE public.first_contact_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sequence_id uuid NOT NULL REFERENCES public.first_contact_sequences(id),step integer NOT NULL CHECK(step BETWEEN 1 AND 4),body text NOT NULL,state text NOT NULL DEFAULT 'sending' CHECK(state IN ('sending','accepted','unknown','failed')),provider_id text,attempted_at timestamptz NOT NULL DEFAULT now(),accepted_at timestamptz,error_code text,UNIQUE(sequence_id,step));
GRANT ALL ON public.first_contact_attempts TO service_role; REVOKE ALL ON public.first_contact_attempts FROM anon,authenticated; ALTER TABLE public.first_contact_attempts ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.first_contact_number(p text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN p ~ '^55[1-9][0-9]9[6-9][0-9]{7}$' THEN left(p,4)||substring(p,6) ELSE p END $$;
REVOKE ALL ON FUNCTION public.first_contact_number(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.first_contact_number(text) TO service_role;
CREATE OR REPLACE FUNCTION public.arm_first_contact_queue() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.first_contact_settings; j bigint; BEGIN
 SELECT * INTO s FROM public.first_contact_settings WHERE company_key='crm:1' FOR UPDATE;
 IF s.enabled AND s.runtime_ready AND length(s.job_secret)>=32 AND EXISTS(SELECT 1 FROM public.first_contact_sequences WHERE state='pending') THEN
  IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='crm-first-contact-pending') THEN PERFORM cron.schedule('crm-first-contact-pending','5 seconds','SELECT net.http_post(url:=''https://project--35f32e53-6c82-48bf-beea-4b5125aef274.lovable.app/api/public/jobs/first-contact'',headers:=jsonb_build_object(''Content-Type'',''application/json'',''Authorization'',''Bearer ''||job_secret),body:=''{}''::jsonb,timeout_milliseconds:=20000) FROM public.first_contact_settings WHERE enabled AND runtime_ready AND company_key=''crm:1'''); END IF;
 ELSE SELECT jobid INTO j FROM cron.job WHERE jobname='crm-first-contact-pending'; IF j IS NOT NULL THEN PERFORM cron.unschedule(j); END IF; END IF;
END $$;
REVOKE ALL ON FUNCTION public.arm_first_contact_queue() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.arm_first_contact_queue() TO service_role;
CREATE OR REPLACE FUNCTION public.save_first_contact_settings(p_author uuid,p_enabled boolean,p_instance text,p_phone text,p_interval integer,p_revision uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.first_contact_settings; BEGIN
 IF NOT public.commercial_knowledge_access(p_author,'crm:1') OR NOT EXISTS(SELECT 1 FROM public.portal_admin_channels WHERE user_id=p_author AND company_key='crm:1' AND instance=p_instance AND public.first_contact_number(canonical_phone)=public.first_contact_number(p_phone)) OR EXISTS(SELECT 1 FROM public.portal_admin_channels WHERE instance=p_instance AND company_key<>'crm:1') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;
 INSERT INTO public.first_contact_settings(company_key) VALUES('crm:1') ON CONFLICT DO NOTHING; SELECT * INTO s FROM public.first_contact_settings WHERE company_key='crm:1' FOR UPDATE;
 IF s.revision<>p_revision THEN RETURN false; END IF;
 IF p_enabled AND (NOT s.runtime_ready OR length(coalesce(s.job_secret,''))<32) THEN RAISE EXCEPTION 'runtime_not_ready'; END IF;
 UPDATE public.first_contact_settings SET enabled=p_enabled,instance=p_instance,sender_phone=p_phone,authorized_by=p_author,interval_seconds=p_interval,revision=gen_random_uuid(),updated_at=now() WHERE company_key='crm:1';
 UPDATE public.first_contact_sequences SET state='cancelled',reason='settings_changed',completed_at=now() WHERE state IN ('pending','sending'); PERFORM public.arm_first_contact_queue(); RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.save_first_contact_settings(uuid,boolean,text,text,integer,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.save_first_contact_settings(uuid,boolean,text,text,integer,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.enroll_first_contact(p_lead uuid,p_event text,p_phone text,p_first text,p_consent_at timestamptz,p_version text,p_origin text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.first_contact_settings; l public.leads; k text; n integer; BEGIN
 SELECT * INTO s FROM public.first_contact_settings WHERE company_key='crm:1' FOR UPDATE; IF NOT coalesce(s.enabled AND s.runtime_ready,false) THEN RETURN 'disabled'; END IF;
 IF p_origin<>'https://trafego.gravoncompany.com' OR length(p_event) NOT BETWEEN 1 AND 200 OR p_consent_at IS NULL OR p_consent_at>now()+interval '5 minutes' OR length(p_version) NOT BETWEEN 1 AND 160 OR p_phone !~ '^[1-9][0-9]{9,14}$' OR length(trim(p_first)) NOT BETWEEN 1 AND 80 THEN RETURN 'ineligible'; END IF;
 SELECT * INTO l FROM public.leads WHERE id=p_lead FOR UPDATE; k:=public.first_contact_number(p_phone);
 IF l.id IS NULL OR l.stage<>'lead-novo' OR l.pipeline_id IS NOT NULL OR public.first_contact_number(CASE WHEN length(regexp_replace(l.whatsapp,'[^0-9]','','g')) IN (10,11) THEN '55'||regexp_replace(l.whatsapp,'[^0-9]','','g') ELSE regexp_replace(l.whatsapp,'[^0-9]','','g') END)<>k OR k=public.first_contact_number(s.sender_phone) THEN RETURN 'ineligible'; END IF;
 IF EXISTS(SELECT 1 FROM public.first_contact_sequences WHERE submission_id=p_event OR contact_key=k) THEN RETURN 'duplicate'; END IF;
 SELECT count(*) INTO n FROM public.leads WHERE public.first_contact_number(CASE WHEN length(regexp_replace(whatsapp,'[^0-9]','','g')) IN (10,11) THEN '55'||regexp_replace(whatsapp,'[^0-9]','','g') ELSE regexp_replace(whatsapp,'[^0-9]','','g') END)=k; IF n<>1 THEN RETURN 'ambiguous_contact'; END IF;
 INSERT INTO public.first_contact_sequences(lead_id,submission_id,contact_key,phone,first_name,lead_name,instance,sender_phone,settings_revision,consent_at,consent_version,form_origin) VALUES(p_lead,p_event,k,p_phone,p_first,l.name,s.instance,s.sender_phone,s.revision,p_consent_at,p_version,p_origin) ON CONFLICT DO NOTHING;
 IF NOT FOUND THEN RETURN 'duplicate'; END IF; PERFORM public.arm_first_contact_queue(); RETURN 'enrolled';
END $$;
REVOKE ALL ON FUNCTION public.enroll_first_contact(uuid,text,text,text,timestamptz,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.enroll_first_contact(uuid,text,text,text,timestamptz,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.cancel_first_contact(p_instance text,p_phone text,p_id text,p_at timestamptz,p_ambiguous boolean DEFAULT false) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.first_contact_sequences; n integer:=0; BEGIN
 PERFORM 1 FROM public.first_contact_settings WHERE company_key='crm:1' FOR UPDATE;
 FOR q IN SELECT * FROM public.first_contact_sequences WHERE instance=p_instance AND (p_ambiguous OR contact_key=public.first_contact_number(p_phone)) AND state IN ('pending','sending','completed') AND (p_ambiguous OR p_at>=started_at) AND inbound_id IS NULL FOR UPDATE LOOP
 UPDATE public.first_contact_sequences SET state=CASE WHEN q.state='completed' THEN 'completed' ELSE 'cancelled' END,reason=CASE WHEN p_ambiguous THEN 'identity_review' ELSE 'lead_replied' END,inbound_id=p_id,completed_at=coalesce(completed_at,now()) WHERE id=q.id;
 IF NOT p_ambiguous THEN UPDATE public.leads SET history=coalesce(history,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('id','first-contact-reply-'||q.id::text,'date',now(),'text','Resposta recebida no WhatsApp. Atendimento manual necessário.','kind','first_contact_reply')) WHERE id=q.lead_id; END IF; n:=n+1; END LOOP;
 PERFORM public.arm_first_contact_queue(); RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.cancel_first_contact(text,text,text,timestamptz,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cancel_first_contact(text,text,text,timestamptz,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.first_contact_inbound_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT NEW.from_me THEN PERFORM public.cancel_first_contact(NEW.instance,NEW.phone,NEW.message_id,NEW.sent_at,false); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.first_contact_inbound_trigger() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER first_contact_cancel_on_inbound AFTER INSERT ON public.whatsapp_messages FOR EACH ROW EXECUTE FUNCTION public.first_contact_inbound_trigger();